**Gates before launch.** `spe/predictions/r04.yaml` and `spe/plans/r04.md` are already committed. I save this script as `spe/evals/harness/r04-workflow.js` and commit it locally. Then I run three gates in order and stop at the first one that fails.

1. **Grader selftest.** `grade.py` must score the oracle labels from `answers.json` 50 of 50 on both fields. It must score empty labels and shifted wrong labels 0. `judge.md` must pass a known polite reply and fail a known rude one. This gate also checks the ticket count. The original eval set had 40 tickets and the approved plan says 50. If `answers.json` holds 40, I halt and ask you, because the saved prediction assumes 50.
2. **Control.** I regrade round 3's outputs with this round's `grade.py` and `judge.md`. Then I compare them with round 3's measured numbers in `spe/prediction-log.md`. Any change is a grader change. It goes into `spe/failures.md` with the old and new numbers side by side.
3. **Dry run.** I run `args.only` on 3 cells: one B ticket, one C2 ticket, and one C2 ticket that needs `check_status`. Each gets 1 trial. I check that every phase returns valid output. I also read the real cost per trial and per judge call to set `estTrialUsd` and `estJudgeUsd`.

The full run is 500 trials, 50 judge calls, up to 40 top-ups, and synthesis. If the projected cost is over $40, I ask you before cutting anything. The cost estimate stays unmeasured until the dry run.

I assumed a runner at `scripts/run-triage.sh` and a `grade.py` that reads JSONL on stdin. The selftest and the dry run check both of those. The Opus judge is in the same model family as the Sonnet agent, so they may share blind spots. No judge from another model family is available.

```js
// spe/evals/harness/r04-workflow.js
// Args:
//   tickets: string[]          ticket IDs. The count must equal expectedTickets.
//   expectedTickets: 50        from the approved plan
//   trials: 5, capUsd: 40
//   estTrialUsd, estJudgeUsd   measured in the dry run. Required for a full run.
//   wrapperUsd                 per-trial overhead of the wrapper agent, from the dry run
//   only: ['B:T007', 'C2:T031'] dry run on named cells
//   runner, runDir, concurrency, topUpPerCell (5), topUpMax (40), maxVoidFrac (0.1)

export const meta = {
  name: 'triage-spe-round',
  description: 'SPE eval for the triage agent. Configs B and C2, 5 trials per cell, code grader for labels, blind Opus judge for reply tone, spend cap.',
  phases: [
    { title: 'Trials' },
    { title: 'Scan' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

const ROUND = 4;
const RR = 'r' + String(ROUND).padStart(2, '0');

const A = args || {};
const ONLY = A.only || null;
const CONFIGS = A.configs || ['B', 'C2'];
const TICKETS = A.tickets || [];
const EXPECTED_TICKETS = A.expectedTickets ?? 50;
const TRIALS = A.trials ?? 5;
const CAP_USD = A.capUsd ?? 40;
const EST_TRIAL_USD = A.estTrialUsd ?? 0.25;
const EST_JUDGE_USD = A.estJudgeUsd ?? 0.3;
const EST_GRADE_USD = A.estGradeUsd ?? 0.1;
const EST_SYNTH_USD = A.estSynthUsd ?? 3;
const WRAPPER_USD = A.wrapperUsd ?? 0;
const TOPUP_PER_CELL = A.topUpPerCell ?? 5;
const TOPUP_MAX = A.topUpMax ?? 40;
const MAX_VOID_FRAC = A.maxVoidFrac ?? 0.1;
const CONCURRENCY = A.concurrency ?? 10;
const RUNNER = A.runner || 'scripts/run-triage.sh';
const RUN_DIR = A.runDir || `runs/${RR}`;
const TRIAL_MODEL = 'sonnet';
const JUDGE_MODEL = 'opus';

const FORBIDDEN = [
  'spe/evals/graders/',
  'spe/evals/tasks/answers.json',
  'spe/predictions/',
  'spe/plans/',
  'spe/spec/',
  'spe/prediction-log.md',
  'spe/failures.md',
];
const FORBIDDEN_RE = FORBIDDEN.map(p => p.replace(/[.]/g, '\\.')).join('|');
const isForbidden = p => FORBIDDEN.some(f => String(p).includes(f));

// ---- Guards ----
if (!ONLY) {
  if (typeof A.estTrialUsd !== 'number' || typeof A.estJudgeUsd !== 'number') {
    throw new Error('estTrialUsd and estJudgeUsd are required for a full run. Measure them in the dry run first.');
  }
  if (TICKETS.length !== EXPECTED_TICKETS) {
    throw new Error(`args.tickets has ${TICKETS.length} IDs and the approved plan expects ${EXPECTED_TICKETS}. Halt and ask the user.`);
  }
}

// ---- Budget ----
// Synthesis is reserved up front so the run can always finish its analysis.
let spent = EST_SYNTH_USD;
const skipped = [];
function reserve(usd, what) {
  if (spent + usd > CAP_USD) {
    skipped.push({ what, usd });
    log(`SKIP ${what}: $${spent.toFixed(2)} + $${usd.toFixed(2)} would cross the $${CAP_USD} cap`);
    return false;
  }
  spent += usd;
  return true;
}
function settle(reserved, actual) {
  spent += actual - reserved;
}

// ---- Helpers ----
const mean = xs => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null);
const key = c => `${c.cfg}:${c.ticket}`;
const counted = t => t.status === 'completed' && !t.voided && !t.ungraded;
const bothOk = t => t.category_ok === true && t.priority_ok === true;

async function inBatches(thunks, n) {
  const out = [];
  for (let i = 0; i < thunks.length; i += n) {
    out.push(...(await parallel(thunks.slice(i, i + n))));
  }
  return out;
}

function seededShuffle(arr, seedStr) {
  let h = 2166136261;
  for (const ch of seedStr) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    h = Math.imul(h ^ (h >>> 15), 2246822507) >>> 0;
    const j = h % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---- Schemas ----
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'paths_read'],
  properties: {
    status: { enum: ['completed', 'harness_error', 'rate_limited'] },
    error: { type: 'string' },
    label: {
      type: 'object',
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    transcript_path: { type: 'string' },
    metrics: {
      type: 'object',
      properties: {
        runtime_s: { type: 'number' },
        tool_calls: { type: 'number' },
        tool_errors: { type: 'number' },
        tokens_in: { type: 'number' },
        tokens_out: { type: 'number' },
        cost_usd: { type: 'number' },
      },
    },
    paths_read: { type: 'array', items: { type: 'string' } },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['hits'],
  properties: { hits: { type: 'array', items: { type: 'string' } }, error: { type: 'string' } },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    error: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'category_ok', 'priority_ok'],
        properties: { id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rid', 'score', 'pass', 'reason'],
        properties: { rid: { type: 'string' }, score: { type: 'number' }, pass: { type: 'boolean' }, reason: { type: 'string' } },
      },
    },
  },
};

const FA_SCHEMA = {
  type: 'object',
  required: ['types', 'grader_doubts', 'proposals'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { enum: ['agent', 'grader', 'judge', 'harness', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
          existing_id: { type: 'string' },
        },
      },
    },
    grader_doubts: { type: 'array', items: { type: 'string' } },
    proposals: { type: 'array', items: { type: 'string' } },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'halt_reasons'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', properties: { what: { type: 'string' }, severity: { enum: ['blocking', 'minor'] } } } },
    halt_reasons: { type: 'array', items: { type: 'string' } },
  },
};

// ---- Cells ----
const cells = ONLY
  ? ONLY.map(s => { const [cfg, ticket] = s.split(':'); return { cfg, ticket }; })
  : CONFIGS.flatMap(cfg => TICKETS.map(ticket => ({ cfg, ticket })));
const cfgsInRun = [...new Set(cells.map(c => c.cfg))];

// ---- Trial ----
function trialPrompt(cfg, ticket, trial, outDir) {
  return (
    `You run one eval trial of the triage agent. SPE round ${ROUND}, config ${cfg}, ticket ${ticket}, trial ${trial}.\n` +
    `Run exactly this command from the repo root and nothing else:\n` +
    `  ${RUNNER} --config ${cfg} --ticket ${ticket} --trial ${trial} --out ${outDir}\n` +
    `The runner prints one JSON object with label, reply, metrics, and transcript_path. Copy those fields into your result unchanged.\n` +
    `You may read only the runner's output and files under ${outDir}/. Do not open, list, or grep any of these paths: ${FORBIDDEN.join(', ')}.\n` +
    `In paths_read, list every file you opened.\n` +
    `If the runner fails, set status to harness_error. If it hits a rate limit, set status to rate_limited. Put the message in error and stop. Do not retry and do not fix anything.`
  );
}

async function runTrial(cfg, ticket, trial, tag) {
  const id = `${cfg}:${ticket}:t${trial}`;
  const base = { id, cfg, ticket, trial, tag, outDir: `${RUN_DIR}/${cfg}/${ticket}/t${trial}` };
  if (!reserve(EST_TRIAL_USD, id)) return { ...base, status: 'skipped_budget' };
  try {
    const r = await agent(trialPrompt(cfg, ticket, trial, base.outDir), {
      label: id,
      phase: tag === 'topup' ? 'Top-up' : 'Trials',
      schema: TRIAL_SCHEMA,
      model: TRIAL_MODEL,
    });
    const cost = r && r.metrics && r.metrics.cost_usd;
    if (typeof cost === 'number') settle(EST_TRIAL_USD, cost + WRAPPER_USD);
    return { ...r, ...base };
  } catch (e) {
    return { ...base, status: 'harness_error', error: String((e && e.message) || e) };
  }
}

// ---- Scan: void any trial that touched a hidden path ----
async function scan(trials, phaseName) {
  const done = trials.filter(t => t.status === 'completed' && !t.voided);
  for (const t of done) {
    const bad = (t.paths_read || []).filter(isForbidden);
    if (bad.length) t.voided = `wrapper read ${bad.join(', ')}`;
  }
  if (!done.length) return;
  if (!reserve(EST_GRADE_USD, `scan ${phaseName}`)) {
    for (const t of done) if (!t.voided) t.voided = 'not scanned (budget)';
    return;
  }
  const r = await agent(
    `Run this command from the repo root and report its output. Do not open any matched file.\n` +
      `  grep -rlE '${FORBIDDEN_RE}' ${RUN_DIR} || true\n` +
      `Put each matched file path in hits, exactly as grep printed it. If grep itself errors, put the message in error.`,
    { label: `leak scan ${phaseName}`, phase: phaseName, schema: SCAN_SCHEMA, model: TRIAL_MODEL },
  );
  if (r.error) throw new Error(`Leak scan failed: ${r.error}. Halt and report.`);
  for (const t of done) {
    const hit = r.hits.find(h => h.startsWith(t.outDir + '/') || h === t.transcript_path);
    if (hit && !t.voided) t.voided = `transcript names a hidden path: ${hit}`;
  }
}

// ---- Grade: code checks on label.category and label.priority ----
async function grade(trials, phaseName) {
  const todo = trials.filter(t => t.status === 'completed' && !t.voided);
  const chunks = [];
  for (let i = 0; i < todo.length; i += 100) chunks.push(todo.slice(i, i + 100));
  await inBatches(
    chunks.map((ch, i) => async () => {
      if (!reserve(EST_GRADE_USD, `grade ${phaseName} ${i}`)) {
        ch.forEach(t => { t.ungraded = 'budget'; });
        return;
      }
      const input = ch.map(t => JSON.stringify({ id: t.id, ticket_id: t.ticket, label: t.label ?? null })).join('\n');
      const r = await agent(
        `Run the code grader on the trial outputs below. Write the lines to a temp file outside the repo, then run:\n` +
          `  python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json < <that file>\n` +
          `The grader prints one JSON line per input with id, category_ok, and priority_ok. Copy those values into results unchanged.\n` +
          `Do not grade anything yourself and do not edit the grader. If the grader errors, put the message in error.\n\n` +
          input,
        { label: `grade ${phaseName} ${i}`, phase: phaseName, schema: GRADE_SCHEMA, model: TRIAL_MODEL },
      );
      if (r.error) throw new Error(`Grader error: ${r.error}. Halt and report.`);
      const byId = new Map(r.results.map(x => [x.id, x]));
      for (const t of ch) {
        const g = byId.get(t.id);
        if (!g) t.ungraded = 'missing from grader output';
        else { t.category_ok = g.category_ok; t.priority_ok = g.priority_ok; }
      }
    }),
    CONCURRENCY,
  );
}

// ---- Judge: reply tone only, blind to config ----
async function judge(trials, phaseName) {
  const todo = trials.filter(t => counted(t) && typeof t.reply === 'string' && t.reply.trim());
  const byTicket = new Map();
  for (const t of todo) {
    if (!byTicket.has(t.ticket)) byTicket.set(t.ticket, []);
    byTicket.get(t.ticket).push(t);
  }
  await inBatches(
    [...byTicket.entries()].map(([ticket, ts]) => async () => {
      if (!reserve(EST_JUDGE_USD, `judge ${phaseName} ${ticket}`)) {
        ts.forEach(t => { t.unjudged = 'budget'; });
        return;
      }
      const shuffled = seededShuffle(ts, `${RR}:${phaseName}:${ticket}`);
      const byRid = new Map(shuffled.map((t, i) => [`R${i + 1}`, t]));
      const body = shuffled.map((t, i) => `--- R${i + 1} ---\n${t.reply}`).join('\n\n');
      const r = await agent(
        `You are the tone judge. Read spe/evals/graders/judge.md and apply its rubric to each reply below.\n` +
          `Read ticket ${ticket} from spe/evals/tasks/ for context. Do not open spe/evals/tasks/answers.json.\n` +
          `Judge tone only. Code checks the labels elsewhere. You are not told which setup wrote which reply. Score each reply on its own and do not rank them against each other.\n\n` +
          body,
        { label: `judge ${phaseName} ${ticket}`, phase: phaseName, schema: JUDGE_SCHEMA, model: JUDGE_MODEL },
      );
      for (const s of r.scores) {
        const t = byRid.get(s.rid);
        if (t) { t.tone_score = s.score; t.tone_pass = s.pass; t.tone_reason = s.reason; }
      }
      ts.forEach(t => { if (typeof t.tone_pass !== 'boolean') t.unjudged = 'missing from judge output'; });
    }),
    CONCURRENCY,
  );
}

// ---- Summaries (base trials only, so top-ups do not overweight hard tickets) ----
function summarize(ts) {
  const out = {};
  for (const cfg of cfgsInRun) {
    const mine = ts.filter(t => t.cfg === cfg);
    const g = mine.filter(counted);
    const judged = g.filter(t => typeof t.tone_pass === 'boolean');
    const m = f => mean(g.map(f).filter(x => typeof x === 'number'));
    out[cfg] = {
      counted: g.length,
      category_acc: mean(g.map(t => (t.category_ok ? 1 : 0))),
      priority_acc: mean(g.map(t => (t.priority_ok ? 1 : 0))),
      both_acc: mean(g.map(t => (bothOk(t) ? 1 : 0))),
      tone_pass_rate: mean(judged.map(t => (t.tone_pass ? 1 : 0))),
      judged: judged.length,
      mean_runtime_s: m(t => t.metrics && t.metrics.runtime_s),
      mean_tool_calls: m(t => t.metrics && t.metrics.tool_calls),
      mean_tool_errors: m(t => t.metrics && t.metrics.tool_errors),
      mean_tokens: m(t => (t.metrics ? (t.metrics.tokens_in || 0) + (t.metrics.tokens_out || 0) : undefined)),
      not_counted: {
        harness_error: mine.filter(t => t.status === 'harness_error').length,
        rate_limited: mine.filter(t => t.status === 'rate_limited').length,
        skipped_budget: mine.filter(t => t.status === 'skipped_budget').length,
        voided: mine.filter(t => t.voided).length,
        ungraded: mine.filter(t => t.status === 'completed' && !t.voided && t.ungraded).length,
      },
    };
  }
  return out;
}

function cellStats(ts) {
  return cells.map(c => {
    const g = ts.filter(t => t.cfg === c.cfg && t.ticket === c.ticket && counted(t));
    return { cell: key(c), n: g.length, both_pass: g.filter(bothOk).length };
  });
}

// ================= Run =================
log(`SPE ${RR}: ${cells.length} cells x ${TRIALS} trials, configs ${cfgsInRun.join(', ')}, cap $${CAP_USD}${ONLY ? ' (dry run)' : ''}`);
let halted = null;

phase('Trials');
const base = await inBatches(
  cells.flatMap(c => Array.from({ length: TRIALS }, (_, k) => () => runTrial(c.cfg, c.ticket, k + 1, 'base'))),
  CONCURRENCY,
);
if (skipped.length) {
  halted = 'budget cap reached during base trials';
  log(`HALT: ${halted}. ${skipped.length} items skipped.`);
}

phase('Scan');
await scan(base, 'Scan');
const voidedBase = base.filter(t => t.voided);
const completedBase = base.filter(t => t.status === 'completed');
if (completedBase.length && voidedBase.length / completedBase.length > MAX_VOID_FRAC) {
  halted = `possible answer-key leak: ${voidedBase.length} of ${completedBase.length} trials voided`;
  log(`HALT: ${halted}`);
  return { round: ROUND, halted, voided: voidedBase.map(t => ({ id: t.id, why: t.voided })), skipped };
}

phase('Grade');
await grade(base, 'Grade');

phase('Judge');
await judge(base, 'Judge');

phase('Top-up');
const baseCells = cellStats(base);
const split = baseCells.filter(s => s.n > 0 && s.both_pass > 0 && s.both_pass < s.n).map(s => s.cell);
let topups = [];
if (!halted && split.length) {
  const thunks = [];
  for (let k = 0; k < TOPUP_PER_CELL && thunks.length < TOPUP_MAX; k++) {
    for (const cell of split) {
      if (thunks.length >= TOPUP_MAX) break;
      const [cfg, ticket] = cell.split(':');
      thunks.push(() => runTrial(cfg, ticket, TRIALS + 1 + k, 'topup'));
    }
  }
  log(`Top-up: ${split.length} split cells, ${thunks.length} extra trials (cap ${TOPUP_MAX})`);
  topups = await inBatches(thunks, CONCURRENCY);
  await scan(topups, 'Top-up');
  await grade(topups, 'Top-up');
  await judge(topups, 'Top-up');
}

phase('Synthesis');
const all = [...base, ...topups];
const summary = summarize(base);
const ceiling = ['category_acc', 'priority_acc', 'both_acc', 'tone_pass_rate'].filter(
  k => cfgsInRun.length > 0 && cfgsInRun.every(cfg => summary[cfg][k] === 1),
);
if (ceiling.length) log(`CEILING on ${ceiling.join(', ')}: every config hit the maximum. Check for a leak or grader bug.`);

const failed = all
  .filter(counted)
  .filter(t => !bothOk(t) || t.tone_pass === false || (t.metrics && t.metrics.tool_errors > 0))
  .map(t => ({
    id: t.id, cfg: t.cfg, ticket: t.ticket, tag: t.tag, label: t.label ?? null,
    category_ok: t.category_ok, priority_ok: t.priority_ok,
    tone_pass: t.tone_pass, tone_reason: t.tone_reason,
    tool_errors: t.metrics ? t.metrics.tool_errors : null,
    transcript_path: t.transcript_path,
  }));

const fa = await agent(
  `Analyse the failed trials from SPE round ${ROUND} of the triage agent. Each entry has the trial id, config, ticket, the label it gave, which label checks failed, the tone verdict, tool errors, and the transcript path.\n` +
    `Read transcripts and spe/evals/tasks/answers.json as needed. Read spe/failures.md and reuse an existing F-number when a type matches. Do not read spe/predictions/. Do not write or edit any file.\n` +
    `Group the failures into types. For each type give the name, kind, what happened, how to spot it, the trial ids it was seen in, a proposed fix, and the existing F-number if one matches.\n` +
    `List any sign that the grader or judge is wrong rather than the agent under grader_doubts. End with proposals for round ${ROUND + 1}.\n\n` +
    JSON.stringify(failed),
  { label: 'failure analysis', phase: 'Synthesis', schema: FA_SCHEMA, model: JUDGE_MODEL },
);

const record = {
  plan: { configs: CONFIGS, tickets: EXPECTED_TICKETS, trials_per_cell: TRIALS, cap_usd: CAP_USD, dry_run: !!ONLY },
  summary_base: summary,
  cells: baseCells,
  top_up: { split_cells: split, trials_run: topups.length, cells_after: cellStats(all).filter(s => split.includes(s.cell)) },
  skipped,
  voided: all.filter(t => t.voided).map(t => ({ id: t.id, why: t.voided })),
  ungraded: all.filter(t => t.ungraded).map(t => ({ id: t.id, why: t.ungraded })),
  unjudged: all.filter(t => t.unjudged).map(t => ({ id: t.id, why: t.unjudged })),
  harness_errors: all.filter(t => t.status === 'harness_error' || t.status === 'rate_limited').map(t => ({ id: t.id, status: t.status, error: t.error })),
  ceiling,
  halted,
  failure_types: fa.types.length,
  grader_doubts: fa.grader_doubts,
};

const critic = await agent(
  `You are the completeness critic for SPE round ${ROUND}. The approved plan ran configs ${CONFIGS.join(' and ')} on ${EXPECTED_TICKETS} tickets with ${TRIALS} trials per cell under a $${CAP_USD} cap.\n` +
    `Check the run record below. Every cell must have ${TRIALS} counted trials or a named reason. Every skip must be logged. Voided trials must be named. Grading and judging must cover every counted trial. ` +
    `Harness errors and rate limits must stay out of accuracy. Top-ups must be reported apart from the base numbers. Flag any ceiling and any grader doubt.\n` +
    `List each gap with a severity. List halt reasons: budget cap, leaked answer key, broken grader, or a decision only the user can make. Do not read spe/predictions/ and do not edit files.\n\n` +
    JSON.stringify(record),
  { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: JUDGE_MODEL },
);

return {
  round: ROUND,
  spend_reserved_or_spent_usd: Number(spent.toFixed(2)),
  ...record,
  failure_analysis: fa,
  critic,
};
```
